class ShoppingCart:
    def __init__(self):
        self._items = {}

    def _get_item(self, item):
        return self._items.get(item)

    def _set_item(self, item, price, quantity):
        self._items[item] = {'price': price, 'quantity': quantity}

    def _update_quantity(self, item, quantity):
        if item in self._items:
            self._items[item]['quantity'] = quantity

    def add_item(self, item, price, quantity=1):
        existing = self._get_item(item)
        if existing is not None:
            new_quantity = existing['quantity'] + quantity
            self._set_item(item, price, new_quantity)
        else:
            self._set_item(item, price, quantity)

    def remove_item(self, item, quantity=1):
        existing = self._get_item(item)
        if existing is not None:
            new_quantity = existing['quantity'] - quantity
            if new_quantity > 0:
                self._update_quantity(item, new_quantity)
            else:
                del self._items[item]

    def view_items(self) -> dict:
        return dict(self._items)

    def total_price(self) -> float:
        return self._calculate_total_price()

    def _calculate_total_price(self) -> float:
        return sum(item['quantity'] * item['price'] for item in self._items.values())
